    ..write('model: $modelId\n')
    ..write('baseUrl: $baseUrl\n')
    ..write('mode: $mode\n')
    ..write('approvalMode: $approvalMode\n')
    ..write(_autoUpdateYaml())
    ..write(_allowedToolsYaml())
    ..write(_promptOverridesYaml())
    ..write(_optionalSectionsYaml())
    ..write(_tuiSectionYaml());
