  if (node == null) return false;
  if (node is! YamlMap) {
    throw ConfigException('trajectory must be a map, got: $node');
  }
  var wireDump = false;
  for (final key in node.keys) {
    if (key != 'wireDump') {
      throw ConfigException('unknown "trajectory" key: $key');
