  if (map.isEmpty) return '';
  final buffer = StringBuffer('  stuckTool:\n');
  for (final entry in map.entries) {
    final value = entry.value;
    if (value is List) {
      buffer.write('    ${entry.key}: [${value.join(', ')}]\n');
    } else {
      buffer.write('    ${entry.key}: $value\n');
    }
  }
  return buffer.toString();
}

