      },
    );

    test(
      'a deleted ghost stays deleted: a stale save never resurrects an '
      'entry named after a built-in provider',
      () async {
        configFile(tmp)
          ..createSync(recursive: true)
          ..writeAsStringSync(
            'mode: code\n'
