    models: models,
    mcp: mcp,
    a2a: a2a,
    providerTimeouts: providerTimeouts,
    skillsAccess: skillsAccess,
    skillsDisableShellExecution: skillsDisableShellExecution,
    skillsLiveRediscovery: skillsLiveRediscovery,
    skillToggles: skillToggles,
    memory: memory,
    fabric: fabric,
    cube: cube,
    tools: tools,
    redact: redact,
