  final names = [
    for (final node in raw)
      if (_isGhostProviderEntry(node)) '${(node as Map)['name']}',
  ];
  if (names.isEmpty) return;
  stderr.writeln(
    'warning: dropped customProviders entries named after built-in '
    'providers (${names.join(', ')}) — reserved names, see issue #221',
  );
}

