    compactionJudgeBudgetSeconds: compactionJudgeBudgetSeconds,
    wireDump: wireDump,
    images: images,
    contextWindowCap: contextWindowCap,
    stuckTool: stuckTool,
    agentLoadMode: agentLoadMode,
    powerSleepPrevention: powerSleepPrevention,
