/// scalar: anything but `true`, `false` or the `"notify"` string throws
/// [ConfigException].
AutoUpdateMode autoUpdateModeFromYaml(Object? node) => switch (node) {
  null || 'notify' => AutoUpdateMode.notify,
  true => AutoUpdateMode.on,
  false => AutoUpdateMode.off,
