        await saveCliConfig(
          tmp.path,
          CliConfig(customProviders: [...b.customProviders, entry('kimi_me')]),
        );
        // A (stale) edits ira-1's last-used model and saves after.
        await saveCliConfig(
          tmp.path,
          CliConfig(customProviders: [
