  String apiType = 'openai',
}) => CustomProviderEntry(
  name: name,
  apiType: apiType,
  baseUrl: 'https://$name.example.com/v1',
  modelId: modelId,
);

File configFile(Directory tmp) => File('${tmp.path}/.fah/config.yaml');

List<String> providerNames(CliConfig config) =>
    [for (final e in config.customProviders) e.name];

