jobs:
  staleHours: 48
  logRetentionDays: 7
headless:
  shellJobDrainMs: 600
  shellJobQuietMs: 300
agent:
  mode: pi
  contextWindowCap: 256000
  misuseBreaker: false
quota:
  badge: true
  ttl_minutes: 30
tui:
  theme: ohmypi-dark
trajectory:
  wireDump: true
waiting:
  waitHeartbeatMinutes: 3
power:
  hold: session
''';

