  if (value == null) return null;
  if (value is! int) {
    throw ConfigException(
      '$label: compaction.judgeBudgetSeconds must be a positive int, '
      "got: $value",
    );
  }
  if (value <= 0) {
    throw ConfigException(
      '$label: compaction.judgeBudgetSeconds must be positive, got: $value',
    );
  }
  return value;
}

